import React, { createContext, useContext, useState, useCallback } from 'react';
const LANG_KEY = 'brgy_language';

// HELPER: safe localStorage read
const loadSavedLang = () => {
  try {
    const v = localStorage.getItem(LANG_KEY);
    if (v === 'fil' || v === 'en') return v;
  } catch { /* ignore */ }
  return 'en';
};

