    // ─── BADAC Tab ───
    badac_eyebrow: 'BADAC',
    badac_hero_title: 'Barangay Anti-Drug Abuse Council',
    badac_sub: 'Seek guidance or report concerns related to illegal drug activities and access information about community-based drug prevention and rehabilitation support.',
    badac_fact_cost_label: 'Cost',
    badac_fact_cost_val: 'All services are free',
    badac_fact_privacy_label: 'Privacy',
    badac_fact_privacy_val: 'Strictly confidential',
    badac_fact_visit_label: 'Visiting',
    badac_fact_visit_val: 'Walk in, no appointment needed',
    badac_contact_heading: 'Call or visit BADAC',
    badac_contact_sub: 'Your visit, name, and information will never be shared without your consent.',
    badac_contact_tap: 'Tap to call',
    badac_contact_hours: 'Monday – Friday · 8:00 AM – 5:00 PM',
    badac_contact_address: 'Barangay 3S+ Hall, Malanday, Valenzuela City',
    badac_steps_heading: 'How it works',
    badac_steps_sub: 'Here is what to expect, one step at a time.',
    badac_step1_title: 'Visit the BADAC Office',
    badac_step1_desc: 'Go to Barangay 3S+ Hall and look for the BADAC desk. Walk-in only — no appointment needed. All visits are strictly confidential.',
    badac_step2_title: 'Interview & Profiling',
    badac_step2_desc: 'A trained BADAC officer will conduct a private, non-judgmental interview to understand your situation and needs.',
    badac_step3_title: 'Free Drug Testing',
    badac_step3_desc: 'Voluntary and free drug testing is available on-site. Results are confidential and will not be shared without your consent.',
    badac_step4_title: 'Evaluation at VADAO',
    badac_step4_desc: 'If needed, you will be referred to VADAO (Valenzuela Anti-Drug Abuse Office) for further evaluation and support planning.',
    badac_step5_title: 'Rehabilitation (If Needed)',
    badac_step5_desc: 'Appropriate rehabilitation programs will be recommended. These are voluntary, free, and tailored to your situation.',
    badac_who_heading: 'Who can get help?',
    badac_who1_title: '18 Years Old and Above',
    badac_who1_desc: 'Services are available to adults. Minors must be accompanied by a parent or guardian.',
    badac_who2_title: 'Voluntary Only',
    badac_who2_desc: 'Participation is completely voluntary. No one will be forced to undergo testing or rehabilitation.',
    badac_who3_title: 'Barangay Residents',
    badac_who3_desc: 'Priority is given to residents of Barangay 3S+ Malanday. Others may be referred to their local BADAC.',
    badac_free_heading: 'All of these services are free',
    badac_free_counseling: 'Counseling & Guidance',
    badac_free_drug_test: 'Drug Testing',
    badac_free_vadao: 'VADAO Referral',
    badac_free_rehab: 'Rehabilitation Coordination',
    badac_free_family: 'Family Support',
    badac_edu_heading: 'Understanding drug abuse',
    badac_edu1_title: "It's a Health Issue",
    badac_edu1_desc: 'Drug dependency is recognized as a medical condition — not a moral failure. It can happen to anyone and is treatable with proper support.',
    badac_edu2_title: 'Recovery Is Possible',
    badac_edu2_desc: 'Many residents have successfully recovered through community-based rehabilitation. Early intervention significantly improves outcomes.',
    badac_edu3_title: 'Family Support Matters',
    badac_edu3_desc: 'Family involvement is one of the strongest factors in successful recovery. BADAC provides guidance for families of affected individuals.',
    badac_faq_heading: 'Common questions',
    badac_faq_sub: 'Tap a question to see the answer.',
    badac_faq1_q: 'Will my information be shared with police?',
    badac_faq1_a: 'No. BADAC strictly follows confidentiality protocols. Your visit and information will not be disclosed to law enforcement without your explicit consent, unless required by a court order.',
    badac_faq2_q: 'Is there any fee for BADAC services?',
    badac_faq2_a: 'All BADAC services are completely FREE — including counseling, drug testing, and rehabilitation referral.',
    badac_faq3_q: 'Can I bring someone with me?',
    badac_faq3_a: 'Yes. You may bring a trusted family member or friend for support. All persons present are required to maintain confidentiality.',
    badac_faq4_q: 'What if I am not a drug user but concerned about someone?',
    badac_faq4_a: 'You can visit the BADAC office for guidance on how to help a family member or loved one. Concerned citizens are welcome.',
    badac_faq5_q: 'What is the difference between BADAC and the police?',
    badac_faq5_a: 'BADAC is a barangay-level welfare body focused on rehabilitation and support — not law enforcement. Visiting BADAC is not the same as surrendering to police.',
    badac_legal: 'Legal reference: RA 9165, the Comprehensive Dangerous Drugs Act of 2002',
