    // ─── BADAC Tab ───
    badac_eyebrow: 'BADAC',
    badac_hero_title: 'Barangay Anti-Drug Abuse Council',
    badac_sub: 'Humingi ng gabay o mag-ulat ng mga alalahanin kaugnay ng mga ipinagbabawal na gamot, at magkaroon ng access sa impormasyon tungkol sa pag-iwas at suporta sa rehabilitasyon sa komunidad.',
    badac_fact_cost_label: 'Bayad',
    badac_fact_cost_val: 'Lahat ng serbisyo ay libre',
    badac_fact_privacy_label: 'Pagiging Kumpidensyal',
    badac_fact_privacy_val: 'Mahigpit na kumpidensyal',
    badac_fact_visit_label: 'Pagbisita',
    badac_fact_visit_val: 'Pwedeng mag-walk in, hindi kailangan ng appointment',
    badac_contact_heading: 'Tumawag o pumunta sa BADAC',
    badac_contact_sub: 'Ang iyong pagbisita, pangalan, at impormasyon ay hindi kailanman ibabahagi nang wala ang iyong pahintulot.',
    badac_contact_tap: 'Pindutin para tumawag',
    badac_contact_hours: 'Lunes – Biyernes · 8:00 AM – 5:00 PM',
    badac_contact_address: 'Barangay 3S+ Hall, Malanday, Lungsod ng Valenzuela',
    badac_steps_heading: 'Paano ito isinasagawa',
    badac_steps_sub: 'Narito ang mga hakbang na dapat asahan.',
    badac_step1_title: 'Pumunta sa Tanggapan ng BADAC',
    badac_step1_desc: 'Pumunta sa Barangay 3S+ Hall at hanapin ang BADAC desk. Walk-in lamang — walang appointment na kailangan. Ang lahat ng pagbisita ay mahigpit na kumpidensyal.',
    badac_step2_title: 'Panayam at Profiling',
    badac_step2_desc: 'Ang isang sinanay na opisyal ng BADAC ay magsasagawa ng pribado at walang-paghuhusgang panayam upang maunawaan ang iyong kalagayan at pangangailangan.',
    badac_step3_title: 'Libreng Drug Testing',
    badac_step3_desc: 'Mayroong boluntaryo at libreng drug testing on-site. Kumpidensyal ang mga resulta at hindi ibabahagi nang wala ang iyong pahintulot.',
    badac_step4_title: 'Pagsusuri sa VADAO',
    badac_step4_desc: 'Kung kinakailangan, ikaw ay ire-refer sa VADAO (Valenzuela Anti-Drug Abuse Office) para sa karagdagang pagsusuri at plano ng suporta.',
    badac_step5_title: 'Rehabilitasyon (Kung Kinakailangan)',
    badac_step5_desc: 'Magrerekomenda ng nararapat na rehabilitation program. Ang mga ito ay boluntaryo, libre, at iniakma sa iyong sitwasyon.',
    badac_who_heading: 'Sino ang maaaring humingi ng tulong?',
    badac_who1_title: '18 Taong Gulang Pataas',
    badac_who1_desc: 'Bukas ang mga serbisyo sa mga nasa hustong gulang. Ang mga menor de edad ay kailangang may kasamang magulang o tagapangalaga.',
    badac_who2_title: 'Boluntaryo Lamang',
    badac_who2_desc: 'Ang pakikilahok ay ganap na boluntaryo. Walang sinumang pipiliting sumailalim sa pagsusuri o rehabilitasyon.',
    badac_who3_title: 'Mga Residente ng Barangay',
    badac_who3_desc: 'Prayoridad ang mga residente ng Barangay 3S+ Malanday. Ang iba ay maaaring i-refer sa BADAC ng kanilang sariling barangay.',
    badac_free_heading: 'Lahat ng serbisyong ito ay libre',
    badac_free_counseling: 'Counseling at Patnubay',
    badac_free_drug_test: 'Drug Testing',
    badac_free_vadao: 'Referral sa VADAO',
    badac_free_rehab: 'Koordinasyon sa Rehabilitasyon',
    badac_free_family: 'Suporta para sa Pamilya',
    badac_edu_heading: 'Pag-unawa sa suliranin sa ipinagbabawal na gamot',
    badac_edu1_title: 'Ito ay Isyung Pangkalusugan',
    badac_edu1_desc: 'Ang pagka-depende sa droga ay kinikilala bilang isang medikal na kondisyon — hindi moral na kabiguan. Maaari itong mangyari kaninuman at nagagamot sa pamamagitan ng wastong suporta.',
    badac_edu2_title: 'Posible ang Pagbangon at Paggaling',
    badac_edu2_desc: 'Maraming residente ang matagumpay na nakabangon sa tulong ng community-based rehabilitation. Ang maagang paghingi ng tulong ay lubhang nagpapataas ng tagumpay.',
    badac_edu3_title: 'Mahalaga ang Suporta ng Pamilya',
    badac_edu3_desc: 'Ang suporta ng pamilya ay isa sa pinakamalakas na salik sa matagumpay na paggaling. Nagbibigay ang BADAC ng gabay para sa mga pamilya ng mga apektadong indibidwal.',
    badac_faq_heading: 'Mga karaniwang tanong',
    badac_faq_sub: 'Pindutin ang tanong upang makita ang sagot.',
    badac_faq1_q: 'Ibabahagi ba ang aking impormasyon sa pulisya?',
    badac_faq1_a: 'Hindi. Mahigpit na sinusunod ng BADAC ang mga patakaran sa pagiging kumpidensyal. Ang iyong pagbisita at impormasyon ay hindi ibubunyag sa mga alagad ng batas nang wala ang iyong tahasang pahintulot, maliban kung iniaatas ng kautusan ng hukuman.',
    badac_faq2_q: 'May bayad ba ang mga serbisyo ng BADAC?',
    badac_faq2_a: 'Lahat ng serbisyo ng BADAC ay ganap na LIBRE — kabilang ang counseling, drug testing, at referral sa rehabilitasyon.',
    badac_faq3_q: 'Maaari ba akong magsama ng kasama?',
    badac_faq3_a: 'Oo. Maaari kang magsama ng mapagkakatiwalaang kapamilya o kaibigan bilang suporta. Ang lahat ng naroroon ay inaatasang magpanatili ng kumpidensyalidad.',
    badac_faq4_q: 'Paano kung hindi ako gumagamit ngunit nag-aalala ako para sa iba?',
    badac_faq4_a: 'Maaari kang bumisita sa tanggapan ng BADAC para humingi ng gabay kung paano matutulungan ang kapamilya o mahal sa buhay. Malugod na tinatanggap ang mga nagmamalasakit na mamamayan.',
    badac_faq5_q: 'Ano ang pagkakaiba ng BADAC sa pulisya?',
    badac_faq5_a: 'Ang BADAC ay isang tanggapang pambarangay na nakatutok sa kapakanan, rehabilitasyon, at suporta — hindi pagpapatupad ng batas. Ang pagbisita sa BADAC ay hindi pagsuko sa pulisya.',
    badac_legal: 'Legal na batayan: RA 9165, ang Comprehensive Dangerous Drugs Act of 2002',
